"use client"

import { useState, useEffect } from "react"
import Link from "next/link"
import { Menu, X, ChevronDown } from "lucide-react"
import { cn } from "@/lib/utils"
import { SiteLogo } from "@/components/site-logo"

const navigation = [
  { name: "Home", href: "/#hero" },
  {
    name: "About",
    href: "/#about",
    children: [
      { name: "Ecological Design Principles", href: "/#principles" },
      { name: "Services", href: "/#services" },
      { name: "Systems", href: "/#systems" },
      { name: "Accomplishments", href: "/#accomplishments" },
      { name: "Interior Architecture", href: "/#interior" },
      { name: "Exterior Architecture", href: "/#exterior" },
    ],
  },
  {
    name: "Portfolio",
    href: "/#portfolio",
    children: [
      { name: "Residences", href: "/#residences" },
      { name: "Resorts", href: "/#resorts" },
      { name: "Conceptual Design", href: "/#conceptual" },
    ],
  },
  {
    name: "Resources",
    href: "/#resources",
    children: [
      { name: "FAQ", href: "/#faq" },
      { name: "Articles", href: "/#articles" },
    ],
  },
  {
    name: "Contact",
    href: "/#contact",
    children: [
      { name: "Bookings", href: "/#bookings" },
      { name: "Info", href: "/#contact" },
    ],
  },
]

/** After hero headline fade-in (~0.8s) so desktop nav appears second */
const DESKTOP_HEADER_REVEAL_MS = 900

export function Header() {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false)
  const [isVisible, setIsVisible] = useState(false)
  const [openDropdown, setOpenDropdown] = useState<string | null>(null)

  useEffect(() => {
    const timer = setTimeout(() => setIsVisible(true), DESKTOP_HEADER_REVEAL_MS)
    return () => clearTimeout(timer)
  }, [])

  return (
    <header
      className={cn(
        "absolute top-0 left-0 right-0 z-50 opacity-100 lg:transition-opacity lg:duration-700",
        isVisible
          ? "lg:pointer-events-auto lg:opacity-100"
          : "lg:pointer-events-none lg:opacity-0",
        "border-b border-border/80 bg-[#f8f3ed] shadow-sm"
      )}
    >
      <nav className="mx-auto flex max-w-7xl items-center justify-between gap-2 px-4 py-3 lg:gap-3 lg:px-8 lg:py-5">
        <div className="flex min-w-0 shrink-0 lg:flex-1">
          <Link
            href="/#hero"
            className="-m-1 flex items-center p-1 lg:-m-1.5 lg:p-1.5"
          >
            <SiteLogo priority className="h-10 w-auto md:h-11 lg:h-14" />
          </Link>
        </div>

        {/* Mobile menu button */}
        <div className="flex lg:hidden">
          <button
            type="button"
            className="-m-2 inline-flex items-center justify-center rounded-md p-2 text-foreground lg:-m-2.5 lg:p-2.5"
            onClick={() => setMobileMenuOpen(true)}
          >
            <span className="sr-only">Open main menu</span>
            <Menu className="h-6 w-6" aria-hidden="true" />
          </button>
        </div>

        {/* Desktop navigation */}
        <div className="hidden lg:flex lg:gap-x-10">
          {navigation.map((item) => (
            <div
              key={item.name}
              className="relative"
              onMouseEnter={() => item.children && setOpenDropdown(item.name)}
              onMouseLeave={() => setOpenDropdown(null)}
            >
              <Link
                href={item.href}
                className="flex items-center gap-1 text-sm font-medium tracking-wide text-primary-foreground/90 transition-colors hover:text-primary-foreground lg:text-foreground/90 lg:hover:text-foreground"
              >
                {item.name}
                {item.children && <ChevronDown className="h-3 w-3" />}
              </Link>

              {/* Dropdown */}
              {item.children && openDropdown === item.name && (
                <div className="absolute left-0 top-full pt-2">
                  <div className="w-56 rounded-sm bg-background/95 py-2 shadow-lg backdrop-blur-sm ring-1 ring-border">
                    {item.children.map((child) => (
                      <Link
                        key={child.name}
                        href={child.href}
                        className="block px-4 py-2 text-sm text-foreground transition-colors hover:bg-muted"
                      >
                        {child.name}
                      </Link>
                    ))}
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>

        <div className="hidden lg:flex lg:flex-1 lg:justify-end">
          <Link
            href="/#consultation"
            className="text-sm font-medium tracking-wide text-primary-foreground/90 transition-colors hover:text-primary-foreground lg:text-foreground/90 lg:hover:text-foreground"
          >
            Book Consultation
          </Link>
        </div>
      </nav>

      {/* Mobile menu */}
      <div
        className={cn(
          "lg:hidden",
          mobileMenuOpen ? "fixed inset-0 z-50" : "hidden"
        )}
      >
        <div
          className="fixed inset-0 bg-foreground/20 backdrop-blur-sm"
          onClick={() => setMobileMenuOpen(false)}
        />
        <div className="fixed inset-y-0 right-0 z-50 w-full overflow-y-auto bg-background px-6 py-6 sm:max-w-sm sm:ring-1 sm:ring-border">
          <div className="flex items-center justify-end">
            <button
              type="button"
              className="-m-2.5 rounded-md p-2.5 text-foreground"
              onClick={() => setMobileMenuOpen(false)}
            >
              <span className="sr-only">Close menu</span>
              <X className="h-6 w-6" aria-hidden="true" />
            </button>
          </div>
          <div className="mt-10 flow-root">
            <div className="-my-6 divide-y divide-border">
              <div className="space-y-2 py-6">
                {navigation.map((item) => (
                  <div key={item.name}>
                    <Link
                      href={item.href}
                      className="-mx-3 block rounded-lg px-3 py-2 text-base font-medium text-foreground hover:bg-muted"
                      onClick={() => setMobileMenuOpen(false)}
                    >
                      {item.name}
                    </Link>
                    {item.children && (
                      <div className="ml-4 mt-1 space-y-1">
                        {item.children.map((child) => (
                          <Link
                            key={child.name}
                            href={child.href}
                            className="-mx-3 block rounded-lg px-3 py-1.5 text-sm text-muted-foreground hover:bg-muted hover:text-foreground"
                            onClick={() => setMobileMenuOpen(false)}
                          >
                            {child.name}
                          </Link>
                        ))}
                      </div>
                    )}
                  </div>
                ))}
              </div>
              <div className="py-6">
                <Link
                  href="/#consultation"
                  className="-mx-3 block rounded-lg px-3 py-2.5 text-base font-medium text-primary hover:bg-muted"
                  onClick={() => setMobileMenuOpen(false)}
                >
                  Book Consultation
                </Link>
              </div>
            </div>
          </div>
        </div>
      </div>
    </header>
  )
}
